style.css:
@-moz-document domain("roblox.com") {
/* Change the background color and image */
  body {
    background-color: #f4e1f4 !important; /* Light purple background */
    background-image: url('https://www.example.com/your-image.jpg') !important; /* Replace with your image URL */
    background-size: cover; /* Make the background image cover the entire page */
    background-position: center center; /* Centers the background image */
    color: #6a2c9b !important; /* Purple text color */
    font-family: 'Arial', sans-serif !important; /* Use Arial font */
  }

  /* Style the header (top bar) */
  header {
    background-color: #9b59b6 !important; /* Purple header background */
    color: #fff !important; /* White text in header */
  }

  /* Customize the Roblox logo (top left) */
  .roblox-logo {
    display: none !important; /* Hides the Roblox logo */
  }

  /* Change the color of links */
  a {
    color: #8e44ad !important; /* Purple color for links */
    text-decoration: none !important; /* Remove underline */
  }

  /* Change the link color when hovered */
  a:hover {
    color: #d594f2 !important; /* Light purple color when hovering over links */
    text-decoration: underline !important; /* Add underline on hover */
  }

  /* Customize the buttons (e.g., for login and sign-up) */
  .btn {
    background-color: #8e44ad !important; /* Purple background for buttons */
    color: white !important; /* White text on buttons */
    border-radius: 10px !important; /* Rounded corners for buttons */
    padding: 10px 20px !important; /* Padding for buttons */
  }

  .btn:hover {
    background-color: #9b59b6 !important; /* Slightly lighter purple on hover */
  }

  /* Customize the navbar (top navigation) */
  .nav-links {
    background-color: #9b59b6 !important; /* Purple navbar background */
    color: white !important; /* White text for navbar items */
  }

  /* Style the footer */
  footer {
    background-color: #6a2c9b !important; /* Darker purple footer background */
    color: #f1e1f1 !important; /* Light purple text in footer */
  }

  /* Change the font for main content */
  .text {
    font-family: 'Helvetica', sans-serif !important; /* Set font for main content */
    font-size: 18px !important; /* Increase font size for better readability */
    line-height: 1.6 !important; /* Better line height */
  }

  /* Optional: Hide specific elements (like ads or banners) */
  .ads, .banner {
    display: none !important; /* Hides any ads or banner elements */
  }
}
